pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract SafeGalaxyCoin is ERC20, Ownable {
    uint256 private constant LIQUIDITY_LOCK_DURATION = 365 days; // One year
    uint256 private constant LIQUIDITY_POOL_THRESHOLD = 1e6 ether; // 1 million ETH

    constructor() ERC20("SafeGalaxyCoin", "SGC") {
        _mint(msg.sender, 1000000 * 1e18); // Mint 1 million SGC tokens
    }

    modifier onlyAfterLiquidityLock() {
        require(block.timestamp >= block.timestamp + LIQUIDITY_LOCK_DURATION, "Liquidity lock not expired");
        _;
    }

    function emergencyWithdraw() external onlyOwner {
        require(block.timestamp >= block.timestamp + LIQUIDITY_LOCK_DURATION, "Liquidity lock not expired");
        payable(owner()).transfer(address(this).balance);
    }

    function _beforeTokenTransfer(address from, address to, uint256 amount) internal override onlyAfterLiquidityLock {
        super._beforeTokenTransfer(from, to, amount);
    }

    receive() external payable {
        require(msg.value <= LIQUIDITY_POOL_THRESHOLD, "Exceeded liquidity pool threshold");
    }
}
